SELECT NULL AS "max_rating" FROM "aggregation_book";
SELECT "aggregation_book"."id", "aggregation_book"."isbn", "aggregation_book"."name", "aggregation_book"."pages", "aggregation_book"."rating", "aggregation_book"."price", "aggregation_book"."contact_id", "aggregation_book"."publisher_id", "aggregation_book"."pubdate", COUNT("aggregation_book_authors"."author_id") FILTER (WHERE true) AS "authors_count" FROM "aggregation_book" LEFT OUTER JOIN "aggregation_book_authors" ON ("aggregation_book"."id" = "aggregation_book_authors"."book_id") WHERE "aggregation_book"."id" = 1 GROUP BY "aggregation_book"."id" LIMIT 21;
SELECT MAX("aggregation_book"."rating") FILTER (WHERE true) AS "max_rating" FROM "aggregation_book";
SELECT SUM("__col1") FILTER (WHERE "total_pages" >= 400) FROM (SELECT SUM("aggregation_book"."pages") FILTER (WHERE "aggregation_book"."rating" > 3.0) AS "total_pages", "aggregation_author"."age" AS "__col1" FROM "aggregation_author" LEFT OUTER JOIN "aggregation_book_authors" ON ("aggregation_author"."id" = "aggregation_book_authors"."author_id") LEFT OUTER JOIN "aggregation_book" ON ("aggregation_book_authors"."book_id" = "aggregation_book"."id") GROUP BY "aggregation_author"."id") subquery;
SELECT MAX("aggregation_book"."rating") FILTER (WHERE EXISTS(SELECT 1 AS "a" FROM "aggregation_book_authors" "U0" WHERE "U0"."book_id" = ("aggregation_book"."id") LIMIT 1)) AS "max_rating" FROM "aggregation_book";
SELECT COUNT("aggregation_author"."id") FILTER (WHERE ("aggregation_author"."age" * 2) > 100) AS "cnt" FROM "aggregation_author";
SELECT MAX("__col1") FILTER (WHERE (NOT "authors_have_other_books" AND "has_authors")) FROM (SELECT "aggregation_book"."publisher_id" AS "publisher", EXISTS(SELECT 1 AS "a" FROM "aggregation_book_authors" "U0" WHERE "U0"."book_id" = ("aggregation_book"."id") LIMIT 1) AS "has_authors", EXISTS(SELECT 1 AS "a" FROM "aggregation_book" "V0" INNER JOIN "aggregation_book_authors" "V1" ON ("V0"."id" = "V1"."book_id") WHERE ("V1"."author_id" IN (SELECT "U0"."id" FROM "aggregation_author" "U0" INNER JOIN "aggregation_book" "U1" ON ("U0"."id" = "U1"."contact_id") WHERE "U1"."id" = ("aggregation_book"."id")) AND NOT ("V0"."id" = ("aggregation_book"."id"))) LIMIT 1) AS "authors_have_other_books", "aggregation_book"."rating" AS "__col1" FROM "aggregation_book") subquery;
SELECT COUNT("__col1") FILTER (WHERE "earliest_book_year" = 2008) FROM (SELECT (SELECT EXTRACT(YEAR FROM "U0"."pubdate") AS "pubdate__year" FROM "aggregation_book" "U0" WHERE "U0"."contact_id" = ("aggregation_author"."id") ORDER BY "U0"."pubdate" ASC LIMIT 1) AS "earliest_book_year", "aggregation_author"."id" AS "__col1" FROM "aggregation_author") subquery;
SELECT SUM("aggregation_author"."age") FILTER (WHERE "aggregation_author"."name"::text LIKE 'test%') AS "age" FROM "aggregation_author";
SELECT SUM("count") FROM (SELECT (SELECT COUNT("U0"."id") FILTER (WHERE ("U0"."pages" = ("aggregation_author"."age"))) AS "weird_count" FROM "aggregation_book" "U0" GROUP BY "U0"."id" LIMIT 1) AS "count" FROM "aggregation_author") subquery;
SELECT AVG("aggregation_author"."age") FILTER (WHERE "aggregation_author"."name"::text LIKE 'test%') AS "age" FROM "aggregation_author";
SELECT STDDEV_POP("aggregation_author"."age") FILTER (WHERE "aggregation_author"."name"::text LIKE 'test%') AS "age" FROM "aggregation_author";
SELECT VAR_POP("aggregation_author"."age") FILTER (WHERE "aggregation_author"."name"::text LIKE 'test%') AS "age" FROM "aggregation_author";
SELECT "aggregation_author"."id", "aggregation_author"."name", "aggregation_author"."age", "aggregation_author"."rating", COUNT("aggregation_author_friends"."to_author_id") FILTER (WHERE "T3"."age" > ("aggregation_author"."age")) AS "older_friends_count" FROM "aggregation_author" LEFT OUTER JOIN "aggregation_author_friends" ON ("aggregation_author"."id" = "aggregation_author_friends"."from_author_id") LEFT OUTER JOIN "aggregation_author" "T3" ON ("aggregation_author_friends"."to_author_id" = "T3"."id") WHERE "aggregation_author"."id" IN (SELECT "U0"."id" AS "pk" FROM "aggregation_author" "U0" LEFT OUTER JOIN "aggregation_author_friends" "U1" ON ("U0"."id" = "U1"."from_author_id") LEFT OUTER JOIN "aggregation_author" "U2" ON ("U1"."to_author_id" = "U2"."id") GROUP BY 1 HAVING COUNT("U1"."to_author_id") FILTER (WHERE ("U2"."age" > ("U0"."age"))) >= 2) GROUP BY "aggregation_author"."id" HAVING COUNT("aggregation_author_friends"."to_author_id") FILTER (WHERE ("T3"."age" > ("aggregation_author"."age"))) >= 2 LIMIT 21;
SELECT "aggregation_author"."id", "aggregation_author"."name", "aggregation_author"."age", "aggregation_author"."rating", SUM("aggregation_book"."pages") FILTER (WHERE "aggregation_book"."rating" > 3.0) AS "pages" FROM "aggregation_author" LEFT OUTER JOIN "aggregation_book_authors" ON ("aggregation_author"."id" = "aggregation_book_authors"."author_id") LEFT OUTER JOIN "aggregation_book" ON ("aggregation_book_authors"."book_id" = "aggregation_book"."id") GROUP BY "aggregation_author"."id" ORDER BY "aggregation_author"."id" ASC;
SELECT SUM("T3"."age") FILTER (WHERE NOT ("T3"."name" = 'test' AND "T3"."name" IS NOT NULL)) AS "age" FROM "aggregation_author" LEFT OUTER JOIN "aggregation_author_friends" ON ("aggregation_author"."id" = "aggregation_author_friends"."from_author_id") LEFT OUTER JOIN "aggregation_author" "T3" ON ("aggregation_author_friends"."to_author_id" = "T3"."id") WHERE "aggregation_author"."name" = 'test';
SELECT SUM("aggregation_book"."pages") FILTER (WHERE ("aggregation_publisher"."name" = 'Apress' AND NOT ("T3"."name" = 'test3' AND "T3"."name" IS NOT NULL))) AS "pages" FROM "aggregation_author" LEFT OUTER JOIN "aggregation_author_friends" ON ("aggregation_author"."id" = "aggregation_author_friends"."from_author_id") LEFT OUTER JOIN "aggregation_author" "T3" ON ("aggregation_author_friends"."to_author_id" = "T3"."id") LEFT OUTER JOIN "aggregation_book_authors" ON ("T3"."id" = "aggregation_book_authors"."author_id") LEFT OUTER JOIN "aggregation_book" ON ("aggregation_book_authors"."book_id" = "aggregation_book"."id") LEFT OUTER JOIN "aggregation_publisher" ON ("aggregation_book"."publisher_id" = "aggregation_publisher"."id") WHERE "aggregation_author"."name" = 'test';
